(() => {
'use strict';
const U=window.DW_UI,V=window.DW_VIEWS,DS=window.DW_DESIGN_STATE,clone=value=>JSON.parse(JSON.stringify(value));
const {esc,icon,btn,pill,field,notice,table,section,shell}=U;
const labels={diagnostics:'流程诊断',runRequirements:'运行准备条件',runFrames:'运行调用帧',runEffects:'输入效果',templateNames:'模板命名预览',templateAssets:'已保存模板',matchCandidates:'匹配候选',importedObjects:'导入对象',ocrLanguages:'已安装语言'};
const sourceRows=new Map(),sources=new Map(),snapshots=new Map(),cursors=new Map();
let clock=()=>Date.now();
const utc=value=>new Date(value).toISOString().replace(/\.\d{3}Z$/,'Z');
const fail=code=>{throw Error(code);};
const actorMatches=(a,b)=>['principal','workspace','authorizationVersion'].every(key=>a[key]===b[key]);
const stateLabels={waiting:'等待中',running:'运行中',paused:'已暂停',succeeded:'已完成',failed:'失败',cancelled:'已取消',not_sent:'未发送',in_flight:'发送中',sent:'已发送',verified:'已确认',rejected:'已拒绝',uncertain:'待核对'};
function normalize(value={}){const result={};for(const key of Object.keys(value).sort()){const v=value[key];if(v===''||Array.isArray(v)&&!v.length||key==='minimumScore'&&v===0)continue;result[key]=Array.isArray(v)?[...new Set(v)].sort():typeof v==='string'?v.normalize('NFC'):v;}return result;}
function matches(kind,row,f){const text=(f.text||'').normalize('NFC').toLocaleLowerCase(),fields={diagnostics:['code','message'],runRequirements:['name'],templateNames:['name'],templateAssets:['name'],ocrLanguages:['language']};if(text&&!fields[kind]?.some(key=>String(row[key]||'').normalize('NFC').toLocaleLowerCase().includes(text)))return false;for(const [arg,key]of [['codes','code'],['states','state'],['sources','source'],['kinds','kind']])if(f[arg]?.length&&!f[arg].includes(row[key]))return false;for(const key of ['nodeId','parentId','satisfied','conflict','candidateId','reused','scale'])if(key in f&&row[key]!==f[key])return false;return (row.score??1)>=(f.minimumScore??0);}
function register(kind,rows,version='1'){const ref={collectionId:'collection-'+crypto.randomUUID(),kind,itemCount:rows.length,expiresAt:utc(clock()+1800000)};sources.set(kind,ref);sourceRows.set(ref.collectionId,{rows:clone(rows),version,ref:clone(ref),authorized:true,owner:{principal:'client-synthetic',workspace:'workspace-demo',authorizationVersion:1}});return clone(ref);}
function resetService(){sourceRows.clear();sources.clear();snapshots.clear();cursors.clear();clock=()=>Date.now();for(const [kind,initial]of Object.entries(window.DW_CATALOG.queryFixtures)){const rows=clone(initial);if(kind==='templateNames')while(rows.length<126){const i=rows.length;rows.push({candidateId:'candidate-'+i,name:(i%2?'报表按钮':'筛选入口')+' '+String(i+1).padStart(3,'0'),source:i%2?'rule':'manual',reason:null,conflict:i%3===0});}register(kind,rows);}}
function read(params,actor={principal:'client-synthetic',workspace:'workspace-demo',authorizationVersion:1}){
 const p={filter:{},order:'asc',cursor:null,pageSize:50,includeTotal:false,...params};
 if(!labels[p.kind]||!Number.isInteger(p.pageSize)||p.pageSize<1||p.pageSize>100||!['asc','desc'].includes(p.order)||typeof p.includeTotal!=='boolean')fail('INVALID_PARAMS');
 const allowed={diagnostics:['text','codes','nodeId'],runRequirements:['text','kinds','satisfied'],runFrames:['states','parentId','nodeId'],runEffects:['states'],templateNames:['text','sources','conflict'],templateAssets:['text','candidateId'],matchCandidates:['minimumScore','scale'],importedObjects:['kinds','reused'],ocrLanguages:['text']};
 if(Object.keys(p.filter).some(key=>!allowed[p.kind].includes(key)))fail('INVALID_PARAMS');
 if('text' in p.filter&&(typeof p.filter.text!=='string'||p.filter.text.length>120))fail('INVALID_PARAMS');for(const key of ['satisfied','conflict','reused'])if(key in p.filter&&typeof p.filter[key]!=='boolean')fail('INVALID_PARAMS');for(const key of ['codes','states','sources','kinds'])if(key in p.filter&&(!Array.isArray(p.filter[key])||p.filter[key].length>32||p.filter[key].some(v=>typeof v!=='string')))fail('INVALID_PARAMS');if('minimumScore' in p.filter&&(typeof p.filter.minimumScore!=='number'||p.filter.minimumScore<0||p.filter.minimumScore>1))fail('INVALID_PARAMS');const filters=normalize(p.filter);let snapshot,last=null;
 if(p.cursor!==null){const pointer=cursors.get(p.cursor);if(!pointer)fail('CURSOR_INVALID');snapshot=snapshots.get(pointer.snapshotId);if(!snapshot||clock()>=Date.parse(snapshot.meta.expiresAt))fail('CURSOR_EXPIRED');if(!actorMatches(actor,snapshot.actor))fail('ACCESS_DENIED');if(p.collectionId!==snapshot.collectionId||p.kind!==snapshot.kind||p.pageSize!==snapshot.pageSize||p.order!==snapshot.order||JSON.stringify(filters)!==JSON.stringify(snapshot.filter))fail('CURSOR_QUERY_MISMATCH');last=pointer.lastIndex;if(!sourceRows.get(snapshot.collectionId)?.authorized)fail('ACCESS_DENIED');}
 else{const source=sourceRows.get(p.collectionId),ref=source?.ref;if(!source||!ref||ref.kind!==p.kind||!source.authorized||!actorMatches(actor,source.owner))fail('COLLECTION_NOT_FOUND');if(clock()>=Date.parse(ref.expiresAt))fail('QUERY_SOURCE_EXPIRED');for(const [id,s]of snapshots)if(clock()>=Date.parse(s.meta.expiresAt))snapshots.delete(id);if(snapshots.size>=8)fail('LIMIT_EXCEEDED');const lifetime=['runFrames','runEffects'].includes(p.kind)?60000:300000;const meta={snapshotId:'query-'+crypto.randomUUID(),snapshotAt:utc(clock()),expiresAt:utc(Math.min(clock()+lifetime,Date.parse(ref.expiresAt))),sourceVersion:source.version};snapshot={meta,rows:source.rows,collectionId:p.collectionId,kind:p.kind,filter:filters,order:p.order,pageSize:p.pageSize,actor:clone(actor),nextTokens:new Map()};snapshots.set(meta.snapshotId,snapshot);}
 let indices=snapshot.rows.flatMap((row,index)=>matches(p.kind,row,filters)?[index]:[]);if(p.order==='desc')indices.reverse();const exactCount=p.includeTotal||!Object.keys(filters).length?indices.length:null;if(last!==null)indices=indices.filter(i=>p.order==='desc'?i<last:i>last);const selected=indices.slice(0,p.pageSize);let next=null;if(indices.length>selected.length){const boundary=selected.at(-1);next=snapshot.nextTokens.get(boundary);if(!next){next='cursor-'+crypto.randomUUID();snapshot.nextTokens.set(boundary,next);cursors.set(next,{snapshotId:snapshot.meta.snapshotId,lastIndex:boundary});}}return {collectionId:p.collectionId,kind:p.kind,querySnapshot:clone(snapshot.meta),items:selected.map(index=>({index,value:clone(snapshot.rows[index])})),matchedCount:exactCount,countState:exactCount===null?'notComputed':'exact',nextCursor:next};
}
function close({snapshotId},actor={principal:'client-synthetic',workspace:'workspace-demo',authorizationVersion:1}){const snapshot=snapshots.get(snapshotId);if(snapshot&&!actorMatches(actor,snapshot.actor))fail('ACCESS_DENIED');snapshots.delete(snapshotId);return {closed:true};}
const api={read,close,source:kind=>clone(sources.get(kind)),rows:collectionId=>clone(sourceRows.get(collectionId).rows),expire:snapshotId=>{const s=snapshots.get(snapshotId);if(s)s.meta.expiresAt=utc(clock()-1000);},append:(kind,row)=>{const old=sources.get(kind),data=sourceRows.get(old.collectionId);return register(kind,[...data.rows,clone(row)],String(Number(data.version)+1));},revoke:collectionId=>{sourceRows.get(collectionId).authorized=false;},reset:resetService};
const Q=DS.query={};
function filters(){const value={};if(Q.text)value.text=Q.text;if(Q.kind==='templateNames'&&Q.status!=='全部')value.conflict=Q.status==='有冲突';if(['runFrames','runEffects'].includes(Q.kind)&&Q.status!=='全部')value.states=[Q.status];return value;}
function params(cursor=null){return {collectionId:Q.source.collectionId,kind:Q.kind,filter:filters(),order:Q.order,cursor,pageSize:Q.pageSize,includeTotal:Q.includeTotal};}
function accept(page,version){if(version!==Q.version)return false;Q.page=clone(page);Q.pending=false;Q.dirty=false;Q.error='';return true;}
function query(cursor=null){const request=params(cursor),version=++Q.version;Q.pending=true;Q.lastRequest=clone(request);try{const result=api.read(request);if(accept(result,version)){if(cursor===null){Q.pages=[];Q.requests=[];Q.pageIndex=0;}else Q.pageIndex++;Q.pages[Q.pageIndex]=clone(result);Q.requests[Q.pageIndex]=clone(request);Q.lastResponse=clone(result);}}catch(error){Q.pending=false;Q.error=error.message;}return Q.page;}
function fresh(){if(Q.page)api.close({snapshotId:Q.page.querySnapshot.snapshotId});Q.pages=[];Q.pageIndex=0;Q.source=api.source(Q.kind);query();}
function seed(id){resetService();Object.assign(Q,{kind:'templateNames',source:api.source('templateNames'),text:'',status:'全部',order:'asc',pageSize:50,includeTotal:true,page:null,pages:[],requests:[],pageIndex:0,version:0,pending:false,dirty:false,error:'',lastRequest:null,lastResponse:null});query();if(id==='mcp-query-expired'){api.expire(Q.page.querySnapshot.snapshotId);query(Q.page.nextCursor);}if(id==='mcp-query-error'){Q.order='desc';query(Q.page.nextCursor);}}
const button=(label,action,kind='',disabled=false)=>'<button type="button" class="btn '+kind+'" data-query-action="'+action+'" '+(disabled?'disabled':'')+'>'+esc(label)+'</button>';
const control=(label,value,name,options)=>field(label,value,'',options).replace(/<(input|select)\b/,'<$1 data-query-field="'+name+'"');
const panel=(title,body,extra='')=>'<section class="panel query-panel"><div class="panel-head"><strong>'+title+'</strong>'+extra+'</div><div class="panel-body">'+body+'</div></section>';
function row(value,index){const states={waiting:'等待中',running:'运行中',paused:'已暂停',succeeded:'已完成',failed:'失败',cancelled:'已取消',not_sent:'未发送',in_flight:'发送中',sent:'已发送',verified:'已确认',rejected:'已拒绝',uncertain:'待核对'};if(Q.kind==='templateNames')return [esc(value.name),{ocr:'OCR',rule:'规则命名',manual:'手工名称'}[value.source],pill(value.conflict?'名称冲突':'可用',value.conflict?'amber':'green')];if(Q.kind==='diagnostics')return [esc(value.message),esc(value.code),esc(value.nodeId||'流程')];if(Q.kind==='runRequirements')return [esc(value.name),{input:'输入参数',variable:'变量',target:'目标'}[value.kind],pill(value.satisfied?'已满足':'待填写',value.satisfied?'green':'amber')];if(Q.kind==='ocrLanguages')return [esc(value.language),'语言包','已安装'];if(Q.kind==='matchCandidates')return [(value.score*100).toFixed(1)+'%',value.box.width+' × '+value.box.height,Math.round(value.scale*100)+'%'];if(Q.kind==='templateAssets')return [esc(value.name),'图像模板','已保存'];if(Q.kind==='importedObjects')return [{workflow:'流程',image:'图像模板',trajectory:'输入轨迹'}[value.kind],value.reused?'复用已有版本':'创建新对象','已完成'];if(Q.kind==='runFrames')return [value.parentId===null?'主调用':'子调用',esc(value.nodeId||'已退出'),states[value.state]];return ['输入段',states[value.state],''];}
function view(s){const page=Q.page,kind=Q.kind,showStatus=['templateNames','runFrames','runEffects'].includes(kind),textAllowed=['templateNames','templateAssets','diagnostics','runRequirements','ocrLanguages'].includes(kind);const stateOptions=kind==='templateNames'?['全部','有冲突','无冲突']:kind==='runFrames'?['全部','running','paused','succeeded','failed','cancelled','waiting']:['全部','not_sent','in_flight','sent','verified','rejected','uncertain'];const reason={CURSOR_EXPIRED:['查询已过期','保留当前条件，重新查询第一页。'],CURSOR_QUERY_MISMATCH:['续页条件已变化','排序或筛选已改变，请重新查询。'],CURSOR_INVALID:['无法读取后续结果','重新查询后继续翻页。'],ACCESS_DENIED:['查询权限已变化','重新打开已授权的数据来源。'],LIMIT_EXCEEDED:['查询数量已达上限','关闭已有查询后重试。']};const error=reason[Q.error]||['查询失败','检查条件后重新查询。'];const headers=kind==='templateNames'?['名称','命名来源','名称状态']:kind==='matchCandidates'?['匹配分数','候选区域','尺度']:kind==='diagnostics'?['问题','诊断代码','位置']:['项目','类型或状态','结果'];const summary=page?(page.matchedCount===null?'本页 '+page.items.length+' 项':page.matchedCount+' 项匹配'):'尚未查询';return shell(s,'<main class="page query-page">'+section('集合分页查询','MCP / 查询与结果',btn('工具目录','mcp-tools'))+panel('查询条件','<div class="query-controls">'+control('数据来源',labels[kind],'kind',{select:Object.values(labels)})+(textAllowed?control('名称或内容包含',Q.text,'text'):'')+(showStatus?control(kind==='templateNames'?'名称状态':'状态',stateLabels[Q.status]||Q.status,'status',{select:stateOptions.map(value=>stateLabels[value]||value)}):control('每页数量',String(Q.pageSize),'pageSize',{select:['10','25','50','100']}))+(showStatus?control('每页数量',String(Q.pageSize),'pageSize',{select:['10','25','50','100']}):'<div class="query-count-option"><label class="check"><input type="checkbox" data-query-field="total" '+(Q.includeTotal?'checked':'')+'><span>计算匹配总数</span></label></div>')+control('读取顺序',Q.order==='asc'?'默认顺序':'反向顺序','order',{select:['默认顺序','反向顺序']})+'</div>','<div class="row">'+button('重新查询','fresh')+button('查询','search','primary',Q.pending)+'</div>')+'<div class="query-columns"><div>'+ (Q.error?notice(error[0],error[1],'amber'):Q.dirty?notice('查询条件已修改','点击查询后更新结果。','blue'):'')+panel(labels[kind],'<div class="query-scroll">'+(page?.items.length?table(headers,page.items.map((item,index)=>row(item.value,index))):'<div class="query-empty">'+icon('search',30)+'<strong>没有符合条件的记录</strong><span>调整筛选后重新查询。</span></div>')+'</div><div class="query-pager"><span>第 '+(Q.pageIndex+1)+' 页 · 本页 '+(page?.items.length||0)+' 项</span><div class="row">'+button('上一页','previous','',Q.pageIndex===0||!!Q.error||Q.pending||Q.dirty)+button('下一页','next','',!page?.nextCursor||!!Q.error||Q.pending||Q.dirty)+'</div></div>',pill(summary,'blue'))+'</div><aside class="stack">'+panel('本次查询',table(['项目','当前值'],[['数据来源',esc(labels[kind])],['读取顺序',Q.order==='asc'?'默认顺序':'反向顺序'],['每页数量',String(Q.pageSize)],['后续结果',page?.nextCursor?'有下一页':'已到末页'],['总数',page?.matchedCount===null?'未计算':String(page?.matchedCount??0)]]))+panel('工具请求与返回','<details><summary>请求参数</summary><pre>'+esc(JSON.stringify(Q.lastRequest,null,2))+'</pre></details><details><summary>本页结果</summary><pre>'+esc(JSON.stringify(Q.lastResponse,null,2))+'</pre></details>')+'</aside></div></main>',{active:'settings'});}
V.query=view;
const previous=DS.resetForScreen;DS.resetForScreen=id=>{previous?.(id);if(id.startsWith('mcp-query')||!Q.kind)seed(id);};
document.addEventListener('change',event=>{const name=event.target.dataset.queryField;if(!name)return;const value=event.target.value;if(name==='kind'){if(Q.page)api.close({snapshotId:Q.page.querySnapshot.snapshotId});Q.kind=Object.keys(labels).find(key=>labels[key]===value);Q.source=api.source(Q.kind);Q.status='全部';Q.text='';fresh();}if(name==='text')Q.text=value;if(name==='status')Q.status=Object.keys(stateLabels).find(key=>stateLabels[key]===value)||value;if(name==='order')Q.order=value==='默认顺序'?'asc':'desc';if(name==='pageSize')Q.pageSize=Number(value);if(name==='total')Q.includeTotal=event.target.checked;if(name!=='kind'){Q.version++;Q.pending=false;Q.dirty=true;}window.DW_PROTOTYPE.go('mcp-query');},true);
document.addEventListener('click',event=>{const target=event.target.closest('[data-query-action]');if(!target||target.disabled)return;event.preventDefault();event.stopImmediatePropagation();switch(target.dataset.queryAction){case 'search':case 'fresh':fresh();break;case 'next':if(Q.page?.nextCursor)query(Q.page.nextCursor);break;case 'previous':if(Q.pageIndex>0){const cached=Q.pages[Q.pageIndex-1];if(Date.now()>=Date.parse(cached.querySnapshot.expiresAt))Q.error='CURSOR_EXPIRED';else{Q.pageIndex--;Q.page=clone(cached);Q.lastResponse=clone(cached);Q.lastRequest=clone(Q.requests[Q.pageIndex]);}}break;}window.DW_PROTOTYPE.go('mcp-query');},true);
window.DW_QUERIES={api,state:Q,params,accept,query,fresh,matches};
})();
